import os
import google.cloud.documentai_v1 as documentai

def validate_document_fields(payload, config=None):
    config = config or {}
    # Ensure all required configuration parameters are present
    if not all(k in config for k in ["project_id", "location", "processor_id", "mime_type", "required_fields"]):
        raise ValueError("Missing required configuration parameters in config: project_id, location, processor_id, mime_type, required_fields")

    client = documentai.DocumentProcessorServiceClient()

    processor_name = client.processor_path(
        config["project_id"], config["location"], config["processor_id"]
    )

    # The payload is assumed to be raw document bytes
    # For Document AI, the specific model family/ID is determined by the 'processor_id'
    # (e.g., a specific custom processor or a pre-trained processor like 'form-parser-v1.0')
    raw_document = documentai.RawDocument(content=payload, mime_type=config["mime_type"])

    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)

    response = client.process_document(request=request)

    extracted_fields = {}
    validation_status = {}
    overall_validation_success = True

    document = response.document

    # Extract entities (structured fields) and their confidence scores
    for entity in document.entities:
        # Document AI typically puts the field name in 'type_' and the value in 'mention_text'
        # Confidence is directly available on the entity
        if entity.type_:
            extracted_fields[entity.type_] = {
                "value": entity.mention_text,
                "confidence": entity.confidence
            }

    # Validate required fields against the specified configuration
    for req_field in config["required_fields"]:
        field_name = req_field["name"]
        min_confidence = req_field.get("min_confidence", 0.0) # Default to 0 if not specified

        if field_name in extracted_fields:
            field_data = extracted_fields[field_name]
            if field_data["confidence"] >= min_confidence:
                validation_status[field_name] = {"found": True, "confidence_met": True, "actual_confidence": field_data["confidence"]}
            else:
                validation_status[field_name] = {"found": True, "confidence_met": False, "actual_confidence": field_data["confidence"], "required_confidence": min_confidence}
                overall_validation_success = False
        else:
            validation_status[field_name] = {"found": False, "confidence_met": False}
            overall_validation_success = False

    result = {
        "extracted_fields": extracted_fields,
        "validation_status": validation_status,
        "overall_validation_success": overall_validation_success
    }
    return result
